// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 oldBal;
        try c.balances(address(this)) returns (uint256 __r) { oldBal = __r; } catch { return; }
        uint oldContract = address(c).balance;
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 newBal;
        try c.balances(address(this)) returns (uint256 __r) { newBal = __r; } catch { return; }
        uint newContract = address(c).balance;
        assertTrue(newBal == oldBal + amount && newContract == oldContract + amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
